import { createHash } from "node:crypto";
import { mkdir, readFile, writeFile } from "node:fs/promises";
import { join } from "node:path";
import type { oas31 } from "openapi3-ts";
import {
	type CodegenOptions,
	processOpenApiDocument,
} from "./process-document.ts";

// `@generated` is the marker review tools collapse on, and the one the block65
// comment rules read to tell generated files from hand-written ones. It carries
// no date or revision: those belong to the commit, and a timestamp in a comment
// is the history version control already holds
const BANNER = `/**
 * @generated by @block65/openapi-codegen
 *
 * Do not edit directly
 */`;

// Generated files are usually reformatted after emission (oxfmt etc.), so their
// bytes never match the raw emitter output and comparing them would rewrite
// every file every run. The manifest records what the emitter produced, which
// makes an unchanged file detectable without a stamp inside it
const MANIFEST = ".openapi-codegen-manifest.json";

function revision(text: string): string {
	return createHash("sha256").update(text).digest("hex").slice(0, 32);
}

async function readManifest(path: string): Promise<Record<string, string>> {
	const text = await readFile(path, "utf8").catch(() => {});

	if (text === undefined) {
		return {};
	}

	try {
		const parsed: unknown = JSON.parse(text);
		return typeof parsed === "object" && parsed !== null
			? (parsed as Record<string, string>)
			: {};
	} catch {
		return {};
	}
}

export async function build(
	inputFile: string,
	outputDir: string,
	tags?: string[],
	options?: CodegenOptions,
) {
	const apischema = (await import(inputFile, {
		with: { type: "json" },
	})) as { default: oas31.OpenAPIObject };

	const {
		commandsFile,
		commandsValidatedFile,
		typesFile,
		mainFile,
		valibotFile,
		honoFile,
		enumsFile,
	} = await processOpenApiDocument(outputDir, apischema.default, tags, options);

	const files = [
		commandsFile,
		typesFile,
		mainFile,
		valibotFile,
		honoFile,
		...(commandsValidatedFile.getStatements().length > 0
			? [commandsValidatedFile]
			: []),
		...(enumsFile.getStatements().length > 0 ? [enumsFile] : []),
	];

	await mkdir(outputDir, { recursive: true });

	const manifestPath = join(outputDir, MANIFEST);
	const previous = await readManifest(manifestPath);
	const next: Record<string, string> = {};

	for (const file of files) {
		try {
			file.formatText();
		} catch (err) {
			console.warn(err);
		}

		const contents = `${BANNER}\n${file.getFullText()}`;
		const name = file.getBaseName();
		const rev = revision(contents);

		next[name] = rev;

		const unchanged =
			previous[name] === rev &&
			(await readFile(file.getFilePath(), "utf8")
				.then(() => true)
				.catch(() => false));

		if (unchanged) {
			continue;
		}

		await writeFile(file.getFilePath(), contents);
	}

	await writeFile(manifestPath, `${JSON.stringify(next, null, "\t")}\n`);
}
